begin;create extension if not exists pgtap with schema extensions;select extensions.no_plan();
insert into auth.users(id)select('4e000000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,6)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at)select id,id,'totp','verified',now(),now()from auth.users where id::text like '4e000000-%';
insert into auth.sessions(id,user_id,factor_id,aal)select id,id,id,'aal2'from auth.users where id::text like '4e000000-%';
insert into public.team_profiles(id,full_name,is_active)select id,'Synthetic program staff',id::text not like '%5'from auth.users where id::text like '4e000000-%';
insert into public.team_role_assignments select('4e000000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from(values(1,'platform_owner'),(2,'content_community_lead'),(3,'operations_lead'),(4,'technical_lead'),(5,'operations_lead'))v(n,code)join public.roles r on r.code=v.code;
create function pg_temp.claims(n int,aal text default 'aal2')returns text language sql as $$select json_build_object('sub','4e000000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',aal,'session_id','4e000000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval '1 hour')::bigint)::text$$;
create temp table target(n int,id uuid);grant all on target to authenticated,service_role;
create function pg_temp.t(n int)returns uuid language sql as $$select id from target where target.n=t.n$$;
create function pg_temp.v()returns int language sql as $$select(public.get_staff_opportunity(pg_temp.t(1))->>'version')::int$$;
create function pg_temp.av(n int)returns int language sql as $$select(public.get_program_application(pg_temp.t(n))->>'version')::int$$;
create function pg_temp.copy()returns jsonb language sql as $$select '{"title":"Synthetic program","description":"A local-only synthetic test opportunity.","kind":"training","eligibility":"Relevant test skills","requirements":"Test requirements","coverId":null}'::jsonb$$;
create function pg_temp.ops()returns jsonb language sql as $$select '{"duration":"","location":"","mode":null,"opensAt":null,"closesAt":null,"capacity":1,"feeXaf":null,"feeInstructions":""}'::jsonb$$;
create function pg_temp.q()returns jsonb language sql as $$select '[{"id":"track","label":"Track","type":"single_choice","required":true,"options":["Software","Design"]},{"id":"available","label":"Available?","type":"boolean","required":true,"options":[]}]'::jsonb$$;
create function pg_temp.h(v text)returns text language sql as $$select encode(sha256(convert_to(v,'UTF8')),'hex')$$;
create function pg_temp.submit(k text,mail text default 'first@example.invalid',a jsonb default '{"track":"Software","available":false}')returns void language sql as $$select public.submit_program_application(jsonb_build_object('opportunityId',pg_temp.t(1),'formId',pg_temp.t(10),'fullName','Synthetic Applicant','email',mail,'whatsapp',null,'motivation','Synthetic motivation','answers',a,'consent',true,'consentVersion','program-applications-v1'),'BWA-'||md5(k),pg_temp.h('identity:'||mail),pg_temp.h(k),pg_temp.h(mail||a::text),pg_temp.h('program-global'),pg_temp.h('email:'||mail),pg_temp.h('program-scope'))$$;
select extensions.is((select count(*)from public.permissions),37::bigint,'three minimum program permissions added');
select extensions.is((select count(*)from public.role_permissions),73::bigint,'six explicitly scoped mappings');
select extensions.ok(not has_table_privilege('anon','business_private.program_applications','select'),'anonymous applicant reads denied');
select extensions.ok(not has_table_privilege('authenticated','business_private.program_applications','SELECT,INSERT,UPDATE,DELETE'),'direct application CRUD revoked');
select extensions.ok(not has_function_privilege('anon','public.submit_program_application(jsonb,text,text,text,text,text,text,text)','execute'),'anonymous cannot bypass privileged ingress');
select extensions.ok(not has_function_privilege('service_role','public.review_program_application(uuid,int,text,text)','execute'),'ingress key cannot decide applications');
select extensions.ok(not(select public from storage.buckets where id='program-application-documents'),'private document bucket');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3,'aal1'),true);
select extensions.throws_ok($$select public.list_staff_opportunities()$$,'42501',null,'AAL1 listing read denied in definer RPC');
select extensions.throws_ok($$select public.list_program_applications()$$,'42501',null,'AAL1 applicant read denied');
select set_config('request.jwt.claims',pg_temp.claims(6),true);
select extensions.throws_ok($$select public.list_program_applications()$$,'42501',null,'unassigned AAL2 denied');
select set_config('request.jwt.claims',pg_temp.claims(5),true);
select extensions.throws_ok($$select public.list_program_applications()$$,'42501',null,'inactive Operations denied');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.throws_ok($$select public.list_program_applications()$$,'42501',null,'Technology has no broad application access');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
insert into target select 1,(public.save_opportunity_copy(null,0,'synthetic-program',pg_temp.copy())->>'id')::uuid;
select extensions.is(public.get_published_opportunity('synthetic-program'),null::jsonb,'draft unavailable publicly');
select extensions.throws_ok($$select public.configure_program(pg_temp.t(1),1,pg_temp.ops(),pg_temp.q(),false,true)$$,'42501',null,'Content cannot configure windows, fees or forms');
select extensions.throws_ok($$select public.list_program_applications()$$,'42501',null,'Content cannot read applicant records');
select extensions.throws_ok($$select public.save_opportunity_copy(null,0,'synthetic-program',pg_temp.copy())$$,'PT409',null,'slug uniqueness enforced');
select extensions.lives_ok($$select public.publish_opportunity(pg_temp.t(1),pg_temp.v(),true)$$,'Content can explicitly publish');
select extensions.is(public.get_published_opportunity('synthetic-program')->>'availability','closed','publication does not open intake');
select extensions.lives_ok($$select public.save_opportunity_copy(pg_temp.t(1),pg_temp.v(),'synthetic-program',pg_temp.copy()||'{"title":"Private future copy"}')$$,'edit private working copy');
select extensions.is(public.get_published_opportunity('synthetic-program')->>'title','Synthetic program','private draft changes do not leak');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.save_opportunity_copy(null,0,'ops-no-publish',pg_temp.copy())$$,'42501',null,'Operations cannot create editorial copy');
select extensions.throws_ok($$select public.configure_program(pg_temp.t(1),pg_temp.v(),pg_temp.ops(),pg_temp.q(),true,false)$$,'22023',null,'approved-facts attestation required');
select extensions.throws_ok($$select public.configure_program(pg_temp.t(1),pg_temp.v(),pg_temp.ops()||'{"feeXaf":5000}',pg_temp.q(),true,true)$$,'22023',null,'fee requires approved on-site instructions');
select extensions.throws_ok($$select public.configure_program(pg_temp.t(1),pg_temp.v(),pg_temp.ops(),'[{"id":"file","label":"Unsafe","type":"upload","required":true,"options":[]}]',true,true)$$,'22023',null,'unsafe upload questions rejected');
select extensions.lives_ok($$select public.configure_program(pg_temp.t(1),pg_temp.v(),pg_temp.ops(),pg_temp.q(),true,true)$$,'Operations opens approved intake');
select extensions.is(public.get_published_opportunity('synthetic-program')->>'availability','accepting','eligible public intake available');
select extensions.throws_ok($$select public.configure_program(pg_temp.t(1),1,pg_temp.ops(),pg_temp.q(),true,true)$$,'PT409',null,'stale configuration rejected');
insert into target select 10,(public.get_staff_opportunity(pg_temp.t(1))->>'formId')::uuid;
set local role service_role;
select extensions.lives_ok($$select pg_temp.submit('first')$$,'anonymous ingress creates one application with required boolean false');
select extensions.lives_ok($$select pg_temp.submit('first')$$,'unchanged idempotent replay returns safely');
select extensions.lives_ok($$select pg_temp.submit('duplicate')$$,'duplicate address receives generic receipt without overwriting');
select extensions.throws_ok($$select pg_temp.submit('bad-choice','bad@example.invalid','{"track":"Other","available":false}')$$,'22023',null,'invalid configurable answer denied in SQL');
select extensions.throws_ok($$select pg_temp.submit('missing-required','bad@example.invalid','{"track":"Software"}')$$,'22023',null,'missing required answer denied');
select extensions.lives_ok($$select pg_temp.submit('second','second@example.invalid')$$,'second pending application does not reserve a place');
reset role;
select extensions.is((select count(*)from business_private.program_applications where opportunity_id=pg_temp.t(1)),2::bigint,'two unique pending applications despite capacity one');
insert into target select 2,id from business_private.program_applications where reference='BWA-'||md5('first');insert into target select 3,id from business_private.program_applications where reference='BWA-'||md5('second');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.is(public.get_program_application(pg_temp.t(2))->>'status','submitted','no automatic acceptance');
select extensions.throws_ok($$select public.review_program_application(pg_temp.t(2),pg_temp.av(2),'accepted','Premature decision')$$,'22023',null,'review/shortlist prerequisites enforced');
select public.review_program_application(pg_temp.t(2),pg_temp.av(2),'under_review','Synthetic review');select public.review_program_application(pg_temp.t(2),pg_temp.av(2),'shortlisted','Synthetic shortlist');
select public.review_program_application(pg_temp.t(3),pg_temp.av(3),'under_review','Synthetic review');select public.review_program_application(pg_temp.t(3),pg_temp.av(3),'shortlisted','Synthetic shortlist');
select extensions.lives_ok($$select public.review_program_application(pg_temp.t(2),pg_temp.av(2),'accepted','Synthetic acceptance')$$,'accept allocates one place');
select extensions.is(public.get_published_opportunity('synthetic-program')->>'availability','full','capacity closes new applications');
select extensions.throws_ok($$select public.review_program_application(pg_temp.t(3),pg_temp.av(3),'accepted','Overbook')$$,'22023',null,'capacity prevents second acceptance');
select extensions.throws_ok($$select public.configure_program(pg_temp.t(1),pg_temp.v(),pg_temp.ops()||'{"capacity":0}',pg_temp.q(),true,true)$$,'22023',null,'capacity cannot shrink below enrollment');
select extensions.lives_ok($$select public.review_program_application(pg_temp.t(2),pg_temp.av(2),'withdrawn','Independently verified synthetic withdrawal')$$,'accepted withdrawal releases place');
select extensions.is(public.get_published_opportunity('synthetic-program')->>'availability','accepting','released place available again');
select extensions.lives_ok($$select public.review_program_application(pg_temp.t(3),pg_temp.av(3),'accepted','Synthetic replacement acceptance')$$,'remaining shortlisted application may use released place');
select extensions.throws_ok($$select public.review_program_application(pg_temp.t(2),pg_temp.av(2),'under_review','Re-entry not authorized')$$,'22023',null,'withdrawal terminal; no automatic re-entry');
select extensions.throws_ok($$select public.review_program_application(pg_temp.t(3),1,'withdrawn','Stale decision')$$,'PT409',null,'decision concurrency protected');
select extensions.lives_ok($$select public.configure_program(pg_temp.t(1),pg_temp.v(),pg_temp.ops(),pg_temp.q(),false,true)$$,'Operations can explicitly close applications');
set local role service_role;
select extensions.throws_ok($$select pg_temp.submit('late','late@example.invalid')$$,'22023',null,'stale form cannot submit after intake closes');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.ok(not(public.export_program_application_summary()->0)?'email','summary export excludes contacts');
select extensions.is(jsonb_array_length(public.get_program_application(pg_temp.t(2))->'reviews'),4,'decision history retained');
reset role;
insert into business_private.program_application_documents(id,application_id,object_key,display_name,mime_type,size_bytes,sha256_hex)values('4e000000-0000-4000-8000-000000000099',pg_temp.t(2),pg_temp.t(2)::text||'/4e000000-0000-4000-8000-000000000099','Synthetic.pdf','application/pdf',12,repeat('a',64));
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.authorize_program_document('4e000000-0000-4000-8000-000000000099')$$,'42501',null,'quarantined download fails closed');
reset role;update business_private.program_application_documents set scan_status='clean',scanned_at=now()where id='4e000000-0000-4000-8000-000000000099';
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.is(public.authorize_program_document('4e000000-0000-4000-8000-000000000099')->>'bucket','program-application-documents','clean metadata may authorize private download');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.throws_ok($$select public.authorize_program_document('4e000000-0000-4000-8000-000000000099')$$,'42501',null,'no technical document release implies no download access');
reset role;
select extensions.throws_ok($$update business_private.opportunity_forms set questions='[]'where opportunity_id=pg_temp.t(1)$$,'42501',null,'form versions cannot be overwritten');
select extensions.is((select count(*)from business_private.program_enrollments where opportunity_id=pg_temp.t(1)and active),1::bigint,'one active enrollment only');
create function pg_temp.audit_failure()returns trigger language plpgsql as $$begin if new.action like 'program.%' then raise exception 'Synthetic audit failure';end if;return new;end;$$;
create trigger fail_program_audit before insert on public.audit_logs for each row execute function pg_temp.audit_failure();
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.review_program_application(pg_temp.t(3),pg_temp.av(3),'withdrawn','Synthetic audit rollback')$$,'P0001',null,'failed audit blocks decision');
reset role;
select extensions.is((select status from business_private.program_applications where id=pg_temp.t(3)),'accepted','status rolled back after audit failure');
select extensions.is((select count(*)from business_private.program_enrollments where application_id=pg_temp.t(3)and active),1::bigint,'seat release also rolled back');
select * from extensions.finish();rollback;
